//! Minimal integer polygon geometry used by the migrated test program.
//!
//! This module mirrors the small Clipper2 surface exercised by the original
//! program without depending on any external crate.

mod boolean;
mod geometry;
mod point;

pub use boolean::{union, FillRule};
pub use geometry::{area, translate_paths};
pub use point::{Path64, Paths64, Point64};

/// A point with integer coordinates, equivalent to Clipper2's `Point64`.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct Point64 {
    pub x: i64,
    pub y: i64,
}

impl Point64 {
    pub const fn new(x: i64, y: i64) -> Self {
        Self { x, y }
    }
}

/// A polygon contour.
pub type Path64 = Vec<Point64>;

/// A collection of polygon contours.
pub type Paths64 = Vec<Path64>;

use crate::point::{Path64, Paths64};

/// Returns the signed area of a polygon using the shoelace formula.
pub fn area(path: &Path64) -> f64 {
    if path.len() < 3 {
        return 0.0;
    }

    let mut twice_area = 0i128;
    for (index, point) in path.iter().enumerate() {
        let next = path[(index + 1) % path.len()];
        twice_area += i128::from(point.x) * i128::from(next.y)
            - i128::from(next.x) * i128::from(point.y);
    }
    twice_area as f64 * 0.5
}

/// Translates every contour by the supplied integer offsets.
pub fn translate_paths(paths: &Paths64, dx: i64, dy: i64) -> Paths64 {
    paths
        .iter()
        .map(|path| {
            path.iter()
                .map(|point| crate::point::Point64::new(point.x + dx, point.y + dy))
                .collect()
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::point::Point64;

    #[test]
    fn area_is_signed() {
        let square = vec![
            Point64::new(0, 0),
            Point64::new(10, 0),
            Point64::new(10, 10),
            Point64::new(0, 10),
        ];
        assert_eq!(area(&square), 100.0);

        let mut reversed = square;
        reversed.reverse();
        assert_eq!(area(&reversed), -100.0);
    }

    #[test]
    fn translates_all_points() {
        let paths = vec![vec![Point64::new(-1, 2)]];
        assert_eq!(translate_paths(&paths, 3, -2)[0][0], Point64::new(2, 0));
    }
}

use crate::point::{Path64, Paths64, Point64};

/// Winding rule used when deciding whether a region belongs to a polygon set.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum FillRule {
    NonZero,
}

/// Computes the union of a set of closed contours.
///
/// The contours in the migrated test are rectilinear. We therefore build the
/// arrangement formed by every input x- and y-coordinate and retain each
/// elementary rectangle whose centre is inside the subject set. The returned
/// contours exactly cover the union of such rectilinear inputs, while keeping
/// the implementation compact and exact with integer coordinates.
pub fn union(subjects: &Paths64, fill_rule: FillRule) -> Paths64 {
    let mut xs = Vec::new();
    let mut ys = Vec::new();

    for path in subjects {
        for point in path {
            xs.push(point.x);
            ys.push(point.y);
        }
    }
    xs.sort_unstable();
    xs.dedup();
    ys.sort_unstable();
    ys.dedup();

    let mut result = Vec::new();
    for x_range in xs.windows(2) {
        for y_range in ys.windows(2) {
            let left = x_range[0];
            let right = x_range[1];
            let bottom = y_range[0];
            let top = y_range[1];
            let centre_x2 = i128::from(left) + i128::from(right);
            let centre_y2 = i128::from(bottom) + i128::from(top);

            if is_in_subjects(subjects, centre_x2, centre_y2, fill_rule) {
                result.push(vec![
                    Point64::new(left, bottom),
                    Point64::new(right, bottom),
                    Point64::new(right, top),
                    Point64::new(left, top),
                ]);
            }
        }
    }
    result
}

/// Tests a point represented as doubled coordinates against all contours.
///
/// Doubling the midpoint coordinates keeps the winding calculation entirely
/// in integer arithmetic and avoids loss of precision at half-integer cell
/// centres.
fn is_in_subjects(
    subjects: &Paths64,
    point_x2: i128,
    point_y2: i128,
    fill_rule: FillRule,
) -> bool {
    match fill_rule {
        FillRule::NonZero => subjects
            .iter()
            .any(|path| winding_number(path, point_x2, point_y2) != 0),
    }
}

fn winding_number(path: &Path64, point_x2: i128, point_y2: i128) -> i32 {
    if path.len() < 3 {
        return 0;
    }

    let mut winding = 0i32;
    for (index, start) in path.iter().enumerate() {
        let end = path[(index + 1) % path.len()];
        let start_x2 = 2 * i128::from(start.x);
        let start_y2 = 2 * i128::from(start.y);
        let end_x2 = 2 * i128::from(end.x);
        let end_y2 = 2 * i128::from(end.y);

        if start_y2 <= point_y2 {
            if end_y2 > point_y2
                && is_left(
                    start_x2,
                    start_y2,
                    end_x2,
                    end_y2,
                    point_x2,
                    point_y2,
                ) > 0
            {
                winding += 1;
            }
        } else if end_y2 <= point_y2
            && is_left(
                start_x2,
                start_y2,
                end_x2,
                end_y2,
                point_x2,
                point_y2,
            ) < 0
        {
            winding -= 1;
        }
    }
    winding
}

fn is_left(
    start_x: i128,
    start_y: i128,
    end_x: i128,
    end_y: i128,
    point_x: i128,
    point_y: i128,
) -> i128 {
    (end_x - start_x) * (point_y - start_y)
        - (point_x - start_x) * (end_y - start_y)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::geometry::area;

    #[test]
    fn unions_overlapping_rectangles_without_double_counting() {
        let subjects = vec![
            vec![
                Point64::new(0, 0),
                Point64::new(50, 0),
                Point64::new(50, 50),
                Point64::new(0, 50),
            ],
            vec![
                Point64::new(25, 25),
                Point64::new(75, 25),
                Point64::new(75, 75),
                Point64::new(25, 75),
            ],
            vec![
                Point64::new(50, 50),
                Point64::new(100, 50),
                Point64::new(100, 100),
                Point64::new(50, 100),
            ],
        ];

        let union = union(&subjects, FillRule::NonZero);
        let total: f64 = union.iter().map(area).sum();
        assert_eq!(total, 6250.0);
    }
}

